import torch.nn.functional as F, json
p='model.language_model.'; E=W(p+'embed_tokens.weight')
groups={'sign':['positive','negative'],'comparison':['greater','less','equal'],'case':['uppercase','lowercase'],'months':['January','February','March','April','May','June','July','August','September','October','November','December'],'weekday':['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'],'boolean':['True','False'],'directions':['north','south','east','west']}
vs={k:F.normalize(torch.stack([E[encode(s)[-1]] for s in v]),dim=1) for k,v in groups.items()}
allres={}
for layer in [45,50,55,57,58,59]:
 D=F.normalize(W(p+f'layers.{layer}.mlp.down_proj.weight'),dim=0)
 res={}
 for k,V in vs.items():
  sc=((V-V.mean(0))@D).abs().max(0).values; ix=sc.topk(8).indices
  res[k]=[(int(i),round(float(sc[i]),4)) for i in ix]
 print(layer,res); allres[layer]=res
json.dump(allres,open('/work/candidates.json','w')); torch.save(vs,'/work/rawvecs.pt')

import torch.nn.functional as F
p='model.language_model.'; E=W(p+'embed_tokens.weight'); En=F.normalize(E,dim=1)
for layer,ids in [(55,[7309,3728,4936,11562,17776,2409]),(58,[10337,19073,14040,4441]),(50,[3284,1878])]:
 D=W(p+f'layers.{layer}.mlp.down_proj.weight')[:,ids]; U=W(p+f'layers.{layer}.mlp.up_proj.weight')[ids]; G=W(p+f'layers.{layer}.mlp.gate_proj.weight')[ids]
 for title,T in [('output',D),('up',U.T),('gate',G.T)]:
  S=En@F.normalize(T,dim=0)
  for j,i in enumerate(ids):
   print(layer,i,title,[(decode([x]),round(float(S[x,j]),3)) for x in S[:,j].topk(8).indices.tolist()])

